const listAccountIDsAfter = `-- name: ListAccountIDsAfter :many
SELECT id FROM account WHERE id > ? ORDER BY id LIMIT ?
`

type ListAccountIDsAfterParams struct {
	Cursor string
	Limit  int32
}

func (q *Queries) ListAccountIDsAfter(ctx context.Context, arg ListAccountIDsAfterParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listAccountIDsAfter, arg.Cursor, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

